begin;
update public.business_tasks set process_steps = '[{"when":"請求書受領時","who":"購買担当","action":"請求書を受領登録する"},{"when":"登録後","who":"システム","action":"受注・納品データと突合する"},{"when":"突合完了時","who":"購買担当","action":"内容確認を実施する"},{"when":"不一致時","who":"購買担当","action":"仕入先に問い合わせる"}]'::jsonb, input = '[{"name":"仕入請求書","source":"仕入先"},{"name":"受注データ","source":"購買管理システム"},{"name":"納品データ","source":"在庫管理システム"}]'::jsonb, output = '[{"name":"請求書受領記録","source":"購買管理システム"},{"name":"突合結果","source":"購買管理システム"}]'::jsonb where id = 'BT-AP-0001';
update public.business_tasks set process_steps = '[{"when":"仕入伝票作成時","who":"購買担当","action":"仕入伝票を作成する"},{"when":"承認時","who":"購買マネージャー","action":"仕入伝票を承認する"},{"when":"承認後","who":"システム","action":"買掛金を自動計上する"},{"when":"計上後","who":"システム","action":"債務台帳へ登録する"}]'::jsonb, input = '[{"name":"仕入伝票","source":"購買管理システム"},{"name":"納品書","source":"在庫管理システム"}]'::jsonb, output = '[{"name":"買掛金台帳","source":"会計システム"},{"name":"買掛金明細","source":"会計システム"}]'::jsonb where id = 'BT-AP-0002';
update public.business_tasks set process_steps = '[{"when":"支払予定日前","who":"システム","action":"支払対象を抽出する"},{"when":"抽出後","who":"購買担当","action":"支払依頼データを作成する"},{"when":"作成後","who":"購買担当","action":"支払依頼を起票する"},{"when":"起票後","who":"購買マネージャー","action":"内容確認を行う"}]'::jsonb, input = '[{"name":"買掛データ","source":"会計システム"},{"name":"支払条件","source":"購買管理システム"},{"name":"仕入先マスタ","source":"購買管理システム"}]'::jsonb, output = '[{"name":"支払依頼データ","source":"購買管理システム"},{"name":"支払予定一覧","source":"購買管理システム"}]'::jsonb where id = 'BT-AP-0003';
update public.business_tasks set process_steps = '[{"when":"支払依頼受領時","who":"管理者","action":"支払依頼をレビューする"},{"when":"承認時","who":"管理者","action":"支払実行を承認する"},{"when":"差戻し時","who":"管理者","action":"購買担当へ差し戻す"},{"when":"不承認時","who":"管理者","action":"支払を保留する"}]'::jsonb, input = '[{"name":"支払依頼データ","source":"購買管理システム"},{"name":"買掛残高","source":"会計システム"}]'::jsonb, output = '[{"name":"承認結果","source":"購買管理システム"},{"name":"支払実行指示","source":"購買管理システム"}]'::jsonb where id = 'BT-AP-0004';
update public.business_tasks set process_steps = '[{"when":"支払実行日","who":"経理担当","action":"支払データを銀行へ送信する"},{"when":"送信後","who":"銀行システム","action":"支払処理を実行する"},{"when":"処理完了後","who":"システム","action":"支払結果を受信する"},{"when":"エラー時","who":"経理担当","action":"再送または修正を行う"}]'::jsonb, input = '[{"name":"承認済支払データ","source":"購買管理システム"},{"name":"振込口座情報","source":"購買管理システム"}]'::jsonb, output = '[{"name":"支払実行結果","source":"銀行インターフェース"},{"name":"支払明細","source":"会計システム"}]'::jsonb where id = 'BT-AP-0005';
update public.business_tasks set process_steps = '[{"when":"手形発行依頼時","who":"経理担当","action":"手形発行依頼を作成する"},{"when":"承認後","who":"経理担当","action":"手形を発行する"},{"when":"発行後","who":"システム","action":"手形台帳へ登録する"},{"when":"期日到来時","who":"システム","action":"期日管理アラートを発報する"},{"when":"期日時","who":"システム","action":"手形決済を行う"}]'::jsonb, input = '[{"name":"手形発行依頼","source":"購買管理システム"},{"name":"支払条件","source":"購買管理システム"}]'::jsonb, output = '[{"name":"手形台帳","source":"会計システム"},{"name":"期日管理表","source":"会計システム"},{"name":"手形決済結果","source":"会計システム"}]'::jsonb where id = 'BT-AP-0006';
update public.business_tasks set process_steps = '[{"when":"毎週","who":"経理担当","action":"支払予定を確認する"},{"when":"支払実行日","who":"経理担当","action":"支払データを作成する"},{"when":"作成後","who":"経理担当","action":"銀行へ送信する"},{"when":"支払完了後","who":"システム","action":"買掛残高を更新する"},{"when":"支払後","who":"システム","action":"仕入先へ支払通知を送る"}]'::jsonb, input = '[{"name":"買掛残高","source":"会計システム"},{"name":"支払予定","source":"購買管理システム"},{"name":"振込口座情報","source":"購買管理システム"}]'::jsonb, output = '[{"name":"支払実行結果","source":"銀行インターフェース"},{"name":"買掛金消込結果","source":"会計システム"}]'::jsonb where id = 'BT-AP-0007';
update public.business_tasks set process_steps = '[{"when":"毎月","who":"経理担当","action":"買掛残高を集計する"},{"when":"集計後","who":"経理担当","action":"仕入先別残高を確認する"},{"when":"確認後","who":"経理担当","action":"支払計画を策定する"},{"when":"支払計画作成後","who":"経理マネージャー","action":"支払計画を承認する"}]'::jsonb, input = '[{"name":"買掛データ","source":"会計システム"},{"name":"支払条件","source":"購買管理システム"}]'::jsonb, output = '[{"name":"買掛残高一覧","source":"会計システム"},{"name":"支払計画","source":"会計システム"}]'::jsonb where id = 'BT-AP-0008';
update public.business_tasks set process_steps = '[{"when":"新規顧客登録時","who":"与信担当","action":"与信枠を設定する"},{"when":"定期見直し時","who":"与信担当","action":"与信枠を再評価する"},{"when":"与信枠超過時","who":"システム","action":"自動アラートを発報する"},{"when":"アラート発報後","who":"与信担当","action":"出荷保留処理を実施する"},{"when":"例外対応時","who":"与信責任者","action":"特別承認を行う"}]'::jsonb, input = '[{"name":"顧客情報","source":"顧客管理システム"},{"name":"与信枠","source":"与信管理システム"},{"name":"取引実績","source":"販売管理システム"}]'::jsonb, output = '[{"name":"与信枠設定","source":"与信管理システム"},{"name":"限度超過アラート","source":"与信管理システム"},{"name":"出荷保留指示","source":"販売管理システム"}]'::jsonb where id = 'BT-AR-0001';
update public.business_tasks set process_steps = '[{"when":"売上発生時","who":"営業担当","action":"売上伝票を作成する"},{"when":"伝票承認時","who":"営業マネージャー","action":"売上伝票を承認する"},{"when":"承認後","who":"システム","action":"売掛金を自動計上する"},{"when":"計上後","who":"システム","action":"債権台帳へ自動登録する"}]'::jsonb, input = '[{"name":"売上伝票","source":"販売管理システム"},{"name":"出荷情報","source":"在庫管理システム"}]'::jsonb, output = '[{"name":"売掛金台帳","source":"会計システム"},{"name":"売掛金明細","source":"会計システム"}]'::jsonb where id = 'BT-AR-0002';
update public.business_tasks set process_steps = '[{"when":"毎月締め日翌営業日","who":"経理担当","action":"請求対象を抽出する"},{"when":"抽出後","who":"経理担当","action":"請求書を生成する"},{"when":"生成後","who":"システム","action":"電子請求書を送信する"},{"when":"送信後","who":"システム","action":"送信結果を記録する"},{"when":"月末","who":"経理担当","action":"請求データを集計する"}]'::jsonb, input = '[{"name":"請求対象データ","source":"販売管理システム"},{"name":"契約情報","source":"契約管理システム"},{"name":"顧客情報","source":"顧客管理システム"}]'::jsonb, output = '[{"name":"請求書（PDF）","source":"請求書発行システム"},{"name":"電子請求書","source":"請求書発行システム"},{"name":"送信結果","source":"請求書発行システム"}]'::jsonb where id = 'BT-AR-0003';
update public.business_tasks set process_steps = '[{"when":"入金データ受取時","who":"システム","action":"入金データを取り込む"},{"when":"取り込み後","who":"システム","action":"請求データと自動突合する"},{"when":"突合不能時","who":"経理担当","action":"マニュアル消込処理を行う"},{"when":"消込完了後","who":"システム","action":"債権残高を更新する"},{"when":"定期実行時","who":"経理担当","action":"未消込一覧を確認する"}]'::jsonb, input = '[{"name":"入金データ","source":"銀行インターフェース"},{"name":"請求データ","source":"請求書発行システム"}]'::jsonb, output = '[{"name":"消込結果","source":"会計システム"},{"name":"未消込一覧","source":"会計システム"},{"name":"入金消込明細","source":"会計システム"}]'::jsonb where id = 'BT-AR-0004';
update public.business_tasks set process_steps = '[{"when":"毎週","who":"システム","action":"未回収債権を抽出する"},{"when":"抽出後","who":"回収担当","action":"督促状を作成する"},{"when":"督促後も未入金時","who":"回収担当","action":"回収計画を策定する"},{"when":"延滞長期化時","who":"与信担当","action":"与信枠を見直す"},{"when":"異常が見つかった時","who":"回収マネージャー","action":"法的手続を検討する"}]'::jsonb, input = '[{"name":"債権残高","source":"会計システム"},{"name":"入金状況","source":"会計システム"},{"name":"督促履歴","source":"債権管理システム"}]'::jsonb, output = '[{"name":"督促状","source":"債権管理システム"},{"name":"回収計画","source":"債権管理システム"},{"name":"与信枠見直し提案","source":"与信管理システム"}]'::jsonb where id = 'BT-AR-0005';
update public.business_tasks set process_steps = '[{"when":"延滞発生時","who":"回収担当","action":"回収活動を開始する"},{"when":"電話連絡時","who":"回収担当","action":"支払い催促を行う"},{"when":"訪問時","who":"回収担当","action":"現地回収交渉を行う"},{"when":"回収完了時","who":"システム","action":"回収状況を更新する"},{"when":"回収不能時","who":"回収マネージャー","action":"貸倒処理を検討する"}]'::jsonb, input = '[{"name":"延滞債権データ","source":"債権管理システム"},{"name":"顧客連絡先","source":"顧客管理システム"}]'::jsonb, output = '[{"name":"回収計画","source":"債権管理システム"},{"name":"回収状況","source":"債権管理システム"},{"name":"回収履歴","source":"債権管理システム"}]'::jsonb where id = 'BT-AR-0006';
update public.business_tasks set process_steps = '[{"when":"証憑受領時","who":"経理担当","action":"証憑内容を確認する"},{"when":"確認後","who":"経理担当","action":"振替伝票を作成する"},{"when":"作成後","who":"経理担当","action":"仕訳データを入力する"},{"when":"入力後","who":"経理マネージャー","action":"仕訳を承認する"},{"when":"承認後","who":"システム","action":"仕訳帳へ登録する"}]'::jsonb, input = '[{"name":"証憑","source":"紙/電子証憑"},{"name":"振替伝票","source":"経理担当"}]'::jsonb, output = '[{"name":"仕訳データ","source":"会計システム"},{"name":"仕訳帳","source":"会計システム"}]'::jsonb where id = 'BT-GL-0002';
update public.business_tasks set process_steps = '[{"when":"業務データ更新時","who":"システム","action":"自動仕訳を生成する"},{"when":"生成後","who":"システム","action":"仕訳の妥当性をチェックする"},{"when":"チェック後","who":"システム","action":"仕訳帳へ転記する"},{"when":"転記後","who":"システム","action":"転記ログを記録する"}]'::jsonb, input = '[{"name":"売掛計上データ","source":"会計システム"},{"name":"買掛計上データ","source":"会計システム"},{"name":"現金出納データ","source":"現金管理システム"}]'::jsonb, output = '[{"name":"仕訳データ","source":"会計システム"},{"name":"転記ログ","source":"会計システム"}]'::jsonb where id = 'BT-GL-0003';
update public.business_tasks set process_steps = '[{"when":"毎日","who":"システム","action":"仕訳データを集計する"},{"when":"集計後","who":"システム","action":"勘定科目別に累計する"},{"when":"累計後","who":"システム","action":"総勘定元帳を作成する"},{"when":"作成後","who":"経理担当","action":"総勘定元帳を確認する"}]'::jsonb, input = '[{"name":"仕訳データ","source":"会計システム"}]'::jsonb, output = '[{"name":"総勘定元帳","source":"会計システム"}]'::jsonb where id = 'BT-GL-0004';
update public.business_tasks set process_steps = '[{"when":"毎月末","who":"経理担当","action":"試算表作成を開始する"},{"when":"開始後","who":"システム","action":"総勘定元帳から集計する"},{"when":"集計後","who":"システム","action":"試算表を作成する"},{"when":"作成後","who":"システム","action":"貸借整合をチェックする"},{"when":"不一致時","who":"経理担当","action":"原因調査を行う"}]'::jsonb, input = '[{"name":"総勘定元帳","source":"会計システム"}]'::jsonb, output = '[{"name":"試算表","source":"会計システム"},{"name":"貸借整合チェック結果","source":"会計システム"}]'::jsonb where id = 'BT-GL-0005';
update public.business_tasks set process_steps = '[{"when":"毎月末","who":"経理担当","action":"財務諸表作成を開始する"},{"when":"開始後","who":"システム","action":"試算表から集計する"},{"when":"集計後","who":"システム","action":"貸借対照表を作成する"},{"when":"作成後","who":"システム","action":"損益計算書を作成する"},{"when":"作成後","who":"経理マネージャー","action":"財務諸表を確認する"}]'::jsonb, input = '[{"name":"試算表","source":"会計システム"}]'::jsonb, output = '[{"name":"貸借対照表","source":"会計システム"},{"name":"損益計算書","source":"会計システム"}]'::jsonb where id = 'BT-GL-0006';
update public.business_tasks set process_steps = '[{"when":"決算開始時","who":"経理担当","action":"決算整理資料を収集する"},{"when":"収集後","who":"経理担当","action":"整理仕訳を作成する"},{"when":"作成後","who":"経理担当","action":"整理仕訳を計上する"},{"when":"計上後","who":"システム","action":"決算資料を作成する"},{"when":"作成後","who":"経理マネージャー","action":"決算資料を確認する"}]'::jsonb, input = '[{"name":"総勘定元帳","source":"会計システム"},{"name":"決算整理資料","source":"経理部門"}]'::jsonb, output = '[{"name":"整理仕訳","source":"会計システム"},{"name":"決算資料","source":"会計システム"}]'::jsonb where id = 'BT-GL-0007';
update public.business_tasks set process_steps = '[{"when":"固定資産取得時","who":"経理担当","action":"固定資産を登録する"},{"when":"毎月","who":"システム","action":"減価償却費を計算する"},{"when":"計算後","who":"システム","action":"償却仕訳を自動作成する"},{"when":"資産廃棄時","who":"経理担当","action":"廃棄仕訳を計上する"},{"when":"定期実行時","who":"経理担当","action":"固定資産台帳を確認する"}]'::jsonb, input = '[{"name":"固定資産データ","source":"固定資産管理システム"}]'::jsonb, output = '[{"name":"固定資産台帳","source":"固定資産管理システム"},{"name":"償却計算","source":"固定資産管理システム"},{"name":"償却仕訳","source":"会計システム"}]'::jsonb where id = 'BT-GL-0008';
update public.business_tasks set process_steps = '[{"when":"決算完了後","who":"税務担当","action":"税申告資料を収集する"},{"when":"収集後","who":"税務担当","action":"税額計算を行う"},{"when":"計算後","who":"税務担当","action":"税申告書を作成する"},{"when":"作成後","who":"税務マネージャー","action":"税申告書を確認する"},{"when":"確認後","who":"税務担当","action":"税務署へ申告する"}]'::jsonb, input = '[{"name":"総勘定元帳","source":"会計システム"},{"name":"決算資料","source":"会計システム"}]'::jsonb, output = '[{"name":"税申告書","source":"税務管理システム"}]'::jsonb where id = 'BT-GL-0009';
update public.business_tasks set input = '[{"name":"IFRS調整項目","source":""}]'::jsonb, output = '[{"name":"IFRS財務諸表","source":""}]'::jsonb where id = 'BT-GL-0010';
update public.business_tasks set process_steps = '[{"when":"受領時","who":"社内関係者","action":"調査通知の受領・初期確認（調査対象期間・範囲・期限の把握、社内関係者への周知）"},{"when":"適宜","who":"外部税理士・税務担当・経理担当・法務担当・担当部門","action":"調査対応チームの編成と役割割当（経理・税務・法務・担当部門および必要に応じ外部税理士の選定）"},{"when":"作成時","who":"担当部門","action":"対象期間・論点の特定と必要書類リストの作成（帳簿、証憑、契約書、申告書等）"},{"when":"作成時","who":"担当部門","action":"書類の収集・整理・要旨作成（証憑との突合、差異の把握、説明資料・計算書の作成）"},{"when":"提出時","who":"税務担当","action":"税務当局への回答・立会い（回答書の提出、立会い対応、追加要求への対応、交渉）"},{"when":"調査結果の確定後","who":"担当部門","action":"調査結果の確定後の社内処理（更正・修正申告の実施、税額計上、内部報告、再発防止策の実施と記録保存）"}]'::jsonb, input = '[{"name":"税務調査通知書（調査通知・質問書）","source":""},{"name":"会計帳簿・補助簿（総勘定元帳、仕訳帳等）","source":""},{"name":"仕入・売上の請求書・支払伝票・領収書","source":""},{"name":"法人税・消費税等の申告書（対象期間）および過年度申告書の写し","source":""},{"name":"契約書・給与台帳・固定資産台帳など関連証憑","source":""},{"name":"過去の税務調査対応記録・税務顧問レター","source":""},{"name":"内部ポリシー・会計基準の適用判断資料","source":""}]'::jsonb, output = '[{"name":"税務当局へ提出した回答書・証憑一式","source":""},{"name":"調査時の立会議事録・やり取り記録（メール履歴等）","source":""},{"name":"社内向け調査報告書（調査結果・影響額・対応方針）","source":""},{"name":"必要な修正申告書・更正処理の実行記録","source":""},{"name":"再発防止策・改善対応の実施計画と実績記録","source":""},{"name":"証憑の保存・保管完了報告","source":""}]'::jsonb where id = 'BT-GL-0011';
update public.business_tasks set process_steps = '[{"when":"受領時","who":"税務担当","action":"調査通知の受領と初期確認（調査範囲・期間・期日・担当税務署の確認）"},{"when":"作成時","who":"担当部門","action":"必要資料一覧の作成と関係部署への資料依頼（会計・給与・契約等）"},{"when":"提出時","who":"担当部門","action":"収集資料の整理・照合・提出用整形（証憑の抜粋、帳簿・照会回答の準備）"},{"when":"回答時","who":"税務担当","action":"税務職員とのヒアリング・現地調査対応（追加照会への回答、現地説明）"},{"when":"適宜","who":"担当部門","action":"指摘事項の原因調査と是正策の立案・実行（修正仕訳、追加申告、内部手続改善）"},{"when":"作成時","who":"担当部門","action":"是正処理・追加申告の実施と最終報告書作成、関係者への報告および記録保存"}]'::jsonb, input = '[{"name":"調査通知文書（書面・電子）","source":""},{"name":"会計伝票・仕訳帳・総勘定元帳","source":""},{"name":"契約書・取引関連書類","source":""},{"name":"給与台帳・人件費関連資料","source":""},{"name":"過去の申告書・添付書類","source":""},{"name":"過去の税務対応記録・税務調査報告書","source":""},{"name":"内部マニュアル・内部統制手続き","source":""}]'::jsonb, output = '[{"name":"提出資料一式（税務署向け）","source":""},{"name":"照会対応記録（問答・やり取りのログ）","source":""},{"name":"是正処理記録（原因分析、対応策、実施履歴）","source":""},{"name":"修正仕訳・追加申告記録（仕訳伝票、申告書控）","source":""},{"name":"最終報告書（調査結果、対応状況、今後の改善点）","source":""}]'::jsonb where id = 'BT-GL-0012';
commit;